 pet.Loaded+=async delegate{try{await Task.Delay(1200);((DispatcherTimer)F(pet,"animation")).Stop();var w=app.Windows.OfType<SettingsWindow>().Single();
 var legacy=Store.Json.Deserialize<Config>("{\"ToolbarFollowMusic\":true}");legacy.Validate();Check(legacy.ToolbarStyle=="legacy"&&legacy.ToolbarFollowMusic,"旧配置保留工具栏音乐跟随及外观");config.ToolbarStyle="invalid";config.ToolbarTint=900;config.ToolbarOpacity=-9;config.ToolbarColor1="bad";config.Validate();Check(config.ToolbarStyle=="legacy"&&config.ToolbarTint==100&&config.ToolbarOpacity==15&&ToolbarTheme.IsHex(config.ToolbarColor1),"材质、色号与参数校验");config.ToolbarStyle="glass";config.ToolbarColorSource="background";config.ToolbarFlow=true;config.ToolbarPreset=11;var copy=PreferenceTransfer.Import(PreferenceTransfer.Export(config,false));Check(copy.ToolbarStyle=="glass"&&copy.ToolbarColorSource=="background"&&copy.ToolbarFlow&&copy.ToolbarPreset==11,"样式设置随通用偏好迁移");
 var page=Page(w,"工具栏样式");var material=SettingsWindow.Descendants<ComboBox>(page).Single(x=>System.Windows.Automation.AutomationProperties.GetName(x)=="工具栏材质");material.SelectedIndex=3;Check(pet.Settings.ToolbarStyle=="tricolor"&&Store.Load().ToolbarStyle=="tricolor","真实材质选择保存并生效");var presets=SettingsWindow.Descendants<Button>(page).Where(x=>ToolbarTheme.PresetNames.Contains(Convert.ToString(x.Content))).ToArray();Check(presets.Length==12,"十二组可点选渐变预设");presets[4].RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Check(pet.Settings.ToolbarPreset==4&&pet.Settings.ToolbarColorSource=="preset","预设按钮保存颜色来源");
 var music=Page(w,"音乐");Check(music.Children[0] is StackPanel&&SettingsWindow.Descendants<Button>((DependencyObject)music.Children[0]).Any(x=>(string)x.Content=="打开 / 连接网易云音乐"),"音乐连接入口位于首组");var link=Page(w,"ChatGPT 联动");Check(link.Children[1] is WrapPanel&&SettingsWindow.Descendants<Button>((DependencyObject)link.Children[1]).Any(x=>(string)x.Content=="打开 ChatGPT"),"ChatGPT 启动与修复入口位于首组");
 var entry=SettingsWindow.Descendants<Expander>(music).Single(x=>(string)x.Header=="进入听歌状态与切歌衔接");Check(!entry.IsExpanded,"音乐细节默认折叠");w.NavigateCategory("音乐","开始听歌前等待");Check(entry.IsExpanded&&entry.IsVisible,"搜索自动展开隐藏设置");w.NavigateCategory("音乐","");Check(!entry.IsExpanded,"清除搜索恢复原折叠状态");entry.IsExpanded=true;w.NavigateCategory("音乐","开始听歌前等待");w.NavigateCategory("音乐","");Check(entry.IsExpanded,"搜索保留用户手动展开状态");entry.IsExpanded=false;w.Capture(Path.Combine(Store.Root,"music-layout.png"));w.NavigateCategory("ChatGPT 联动","");w.Capture(Path.Combine(Store.Root,"chatgpt-layout.png"));w.NavigateCategory("工具栏样式","");w.Capture(Path.Combine(Store.Root,"toolbar-settings.png"));
 var sheet=new DrawingVisual();using(var dc=sheet.RenderOpen()){dc.DrawRectangle(Brushes.White,null,new Rect(0,0,680,ToolbarTheme.Styles.Length*75));for(int i=0;i<ToolbarTheme.Styles.Length;i++){var c=new Config{ToolbarStyle=ToolbarTheme.Styles[i],ToolbarPreset=i%12};var colors=ToolbarTheme.Tinted(c,ToolbarTheme.ColorsFor(c,null,null),false);var brush=ToolbarTheme.MakeBrush(c,colors,0);dc.DrawText(new FormattedText(ToolbarTheme.StyleNames[i],System.Globalization.CultureInfo.GetCultureInfo("zh-CN"),FlowDirection.LeftToRight,new Typeface("Microsoft YaHei UI"),16,Brushes.Black),new Point(18,i*75+20));dc.DrawRoundedRectangle(brush,new Pen(Brushes.LightGray,.7),new Rect(210,i*75+12,280,44),16,16);Check(brush.Opacity==.85,"保留独立底板透明度："+c.ToolbarStyle);}}
 var bitmap=new RenderTargetBitmap(1360,ToolbarTheme.Styles.Length*150,192,192,PixelFormats.Pbgra32);bitmap.Render(sheet);Save(bitmap,"toolbar-materials");
 var cflow=new Config{ToolbarStyle="tricolor",ToolbarFlow=true};var palette=ToolbarTheme.Tinted(cflow,ToolbarTheme.ColorsFor(cflow,null,null),false);var a=(LinearGradientBrush)ToolbarTheme.MakeBrush(cflow,palette,0);var b=(LinearGradientBrush)ToolbarTheme.MakeBrush(cflow,palette,4);Check(a.StartPoint!=b.StartPoint,"动态渐变随时间变化");cflow.ReduceMotion=true;Check(((LinearGradientBrush)ToolbarTheme.MakeBrush(cflow,palette,0)).StartPoint==((LinearGradientBrush)ToolbarTheme.MakeBrush(cflow,palette,4)).StartPoint,"减少动态效果停止流动");
 w.Hide();backdrop=new Window{Width=600,Height=500,Left=100,Top=100,WindowStyle=WindowStyle.None,ShowInTaskbar=false,Background=Brushes.White};var canvas=new Canvas();for(int i=0;i<20;i++){var stripe=new Border{Width=30,Height=500,Background=i%2==0?Brushes.LightSkyBlue:Brushes.PaleVioletRed};Canvas.SetLeft(stripe,i*30);canvas.Children.Add(stripe);}backdrop.Content=canvas;backdrop.Show();pet.Left=240;pet.Top=150;pet.Settings.ToolbarStyle="glass";pet.Settings.ToolbarOpacity=20;pet.Settings.ToolbarGlassFog=5;pet.Settings.ToolbarPinned=true;pet.Settings.ToolbarColorSource="preset";pet.ApplyAppearanceForSettings();IntPtr foreground=Native.GetForegroundWindow();Call(pet,"SetToolbarVisible",true,false);await Task.Delay(450);Call(pet,"UpdateMusic");await Task.Delay(300);
 Check(Native.GetForegroundWindow()==foreground,"玻璃层显示不抢焦点");var glass=(ToolbarGlass)F(pet,"toolbarGlass");Check(glass.Handle==IntPtr.Zero||Native.IsAbove(new WindowInteropHelper(pet).Handle,glass.Handle),"系统玻璃层位于按钮与宠物下方");IntPtr region=CreateRectRgn(0,0,1,1);int result=GetWindowRgn(glass.Handle,region);Store.Atomic("glass-status.json",new{available=glass.Available,handle=glass.Handle.ToInt64(),region=result,corner=PtInRegion(region,0,0),hint=pet.ToolbarMaterialStatus});DeleteObject(region);
 Native.Rect bounds;Native.GetWindowRect(new WindowInteropHelper(backdrop).Handle,out bounds);using(var image=new System.Drawing.Bitmap(bounds.Width,bounds.Height)){using(var g=System.Drawing.Graphics.FromImage(image))g.CopyFromScreen(bounds.Left,bounds.Top,0,0,image.Size);image.Save(Path.Combine(Store.Root,"native-glass.png"));}

 var menu=new Window{Width=110,Height=80,Left=250,Top=350,Topmost=true,ShowInTaskbar=false,WindowStyle=WindowStyle.None,Background=Brushes.Bisque};menu.Show();IntPtr mh=new WindowInteropHelper(menu).Handle;Set(pet,"fallbackMenu",mh);Call(pet,"UpdateMenuPriority",true);Call(pet,"UpdateMusic");Check(glass.Handle==IntPtr.Zero||Native.IsAbove(mh,glass.Handle)&&Native.IsAbove(mh,new WindowInteropHelper(pet).Handle),"外部菜单出现时玻璃与宠物均让出顶层");Set(pet,"fallbackMenu",IntPtr.Zero);menu.Close();Call(pet,"UpdateMenuPriority",false);Call(pet,"UpdateMusic");Check(glass.Handle==IntPtr.Zero||Native.IsTopmost(glass.Handle)&&Native.IsAbove(new WindowInteropHelper(pet).Handle,glass.Handle),"菜单关闭恢复玻璃顶层且保持按钮在上");
 pet.Hide();Check(glass.Handle==IntPtr.Zero||!Native.IsPresented(glass.Handle),"隐藏宠物同步隐藏玻璃，无悬空底板");pet.Show();
 pet.Settings.ToolbarStyle="legacy";Call(pet,"UpdateMusic");Check(glass.Handle==IntPtr.Zero||!Native.IsPresented(glass.Handle),"关闭玻璃样式立即收起独立底板");pet.Settings.ToolbarStyle="tricolor";Call(pet,"UpdateMusic");Check(((Border)F(pet,"hoverBar")).Background is LinearGradientBrush,"实际工具栏使用选择的渐变");passed=true;
 }catch(Exception e){Store.Atomic("error.json",new{error=e.ToString()});}finally{Store.Atomic("toolbar-theme-tests.json",new{passed,checks});if(backdrop!=null)backdrop.Close();foreach(var win in app.Windows.Cast<Window>().Where(x=>x!=pet).ToArray())win.Close();pet.Close();}};app.Run(pet);return passed?0:1;}
